use std::sync::Arc;
use ospf_rust_core::model::intermediate::LinearTriadModel;
use ospf_rust_core::solver::{
    CancellationOrigin, ProblemStatus, SolveFingerprints, SolveHandle, SolveOptions, SolveReport, SolverCapability,
    SolverInfo, SolverOutput, TerminationReason, linear_model_fingerprint, linear_model_mapping,
};
use ospf_rust_bridge::{Bpp2dOptions, Bpp3dGeneratorKind, ModelKind, decode_bpp3d_execution_report, encode_bpp3d_problem};
use super::*;

struct Fake<F>(F);

impl<F: Send + Sync> SolverInfo for Fake<F> {
    fn name(&self) -> &str { "bpp3d-native-contract" }
    fn capabilities(&self) -> Vec<SolverCapability> { vec![SolverCapability::Linear] }
}

impl<F> LinearSolver for Fake<F>
where F: Fn(&LinearTriadModel) -> ospf_rust_core::Result<SolveReport<f64>> + Send + Sync {
    fn solve_linear(&self, _: &LinearTriadModel) -> ospf_rust_core::Result<SolverOutput> { panic!("report path required") }
    fn solve_linear_report_with_options(&self, model: &LinearTriadModel, _: &SolveOptions<'_>) -> ospf_rust_core::Result<SolveReport<f64>> { (self.0)(model) }
}

/// 无 incumbent 的原始终态报告，保留模型身份但不补方案。 / Original incumbent-free terminal report retaining model identity without invented plans.
fn terminal(model: &LinearTriadModel, reason: TerminationReason) -> ospf_rust_core::Result<SolveReport<f64>> {
    SolveReport::builder(ProblemStatus::Unknown, reason)
        .fingerprints(SolveFingerprints { model: Some(linear_model_fingerprint(model)?), ..Default::default() })
        .model_mapping(Some(linear_model_mapping(model)?)).build()
}

/// 两个同型候选箱共用源初始层即可覆盖两件需求，使真实 final 可行。 / Two identical candidate bins can share the source initial layer, making the real final feasible.
fn problem() -> ospf_rust_bridge::Bpp3dProblem {
    serde_json::from_str(r#"{
        "items":[{"id":"item","name":"Item","width":{"value":1,"unit":"m"},"height":{"value":1,"unit":"m"},"depth":{"value":1,"unit":"m"},"weight":{"value":500,"unit":"g"},"amount":"2","orientations":["upright"]}],
        "bins":[{"id":"one","typeCode":"type","width":{"value":1,"unit":"m"},"height":{"value":1,"unit":"m"},"depth":{"value":1,"unit":"m"},"capacity":{"value":1,"unit":"kg"},"isMain":true},
                {"id":"two","typeCode":"type","width":{"value":1,"unit":"m"},"height":{"value":1,"unit":"m"},"depth":{"value":1,"unit":"m"},"capacity":{"value":1,"unit":"kg"},"isMain":true}],
        "initialLayers":[{"id":"layer","binId":"one","depth":{"value":1,"unit":"m"},"placements":[{"itemId":"item","position":{"x":{"value":0,"unit":"m"},"y":{"value":0,"unit":"m"},"z":{"value":0,"unit":"m"}},"orientation":"upright"}]}]
    }"#).unwrap()
}

fn options() -> Bpp3dOptions {
    Bpp3dOptions { backend: ospf_rust_bridge::NativeBackend::Scip, generators: None, report_limit: None, max_placements: None }
}

