#[test]
fn generator_chain_defaults_to_the_original_standard_chain_and_stays_registered() {
    let standard = options().layer_generation().unwrap();
    assert_eq!(standard.generators.len(), Bpp3dGeneratorKind::DEFAULT_CHAIN.len());
    assert_eq!(Bpp3dGeneratorKind::ALL.len(), Bpp3dGeneratorKind::DEFAULT_CHAIN.len() + 1);
    let explicit = Bpp3dOptions { generators: Some(vec![Bpp3dGeneratorKind::Block]), ..options() };
    assert_eq!(explicit.layer_generation().unwrap().generators.len(), 1);
    let every = Bpp3dOptions { generators: Some(Bpp3dGeneratorKind::ALL.to_vec()), ..options() };
    assert_eq!(every.layer_generation().unwrap().generators.len(), Bpp3dGeneratorKind::ALL.len());
    assert!(Bpp3dOptions { generators: Some(vec![Bpp3dGeneratorKind::Historical]), ..options() }.budgets().is_ok());
}

#[test]
fn incumbent_free_and_cancelled_rmps_stop_the_round_with_real_evidence() {
    let request = request();
    let handle = SolveHandle::new();
    for reason in [TerminationReason::TimeLimit, TerminationReason::Interrupted] {
        let text = execute(&request.model, options(), Arc::new(Fake(move |model: &LinearTriadModel| terminal(model, reason))),
            &SolveOptions { cancellation_handle: Some(&handle), ..Default::default() }).unwrap();
        let report = decode_bpp3d_execution_report(&text, &request.model).unwrap();
        assert!(!report.summary.completed && report.summary.stage_count == 1 && report.summary.final_stage.is_none());
        assert!(report.summary.failure.as_deref().unwrap_or_default().contains("no incumbent"));
        assert!(report.packing.is_none() && report.selection.is_none());
        let stage = &report.stages[0];
        assert!(!stage.restricted_optimal && !stage.has_incumbent && stage.objective_value.is_none());
        assert!(stage.problem_status.is_some() && stage.termination_reason.is_some());
    }
    // 预取消经共享取消句柄进入真实终态报告，不调用求解器也不伪造成功。 / Pre-cancellation reaches the real terminal report through the shared handle without calling the solver or inventing success.
    let cancelled = SolveHandle::new();
    cancelled.cancel(CancellationOrigin::External);
    let text = execute(&request.model, options(), Arc::new(Fake(|model: &LinearTriadModel| terminal(model, TerminationReason::Completed))),
        &SolveOptions { cancellation_handle: Some(&cancelled), ..Default::default() }).unwrap();
    let report = decode_bpp3d_execution_report(&text, &request.model).unwrap();
    assert!(!report.summary.completed);
    assert_eq!(report.stages[0].termination_reason.as_deref(), Some("CANCELLED"));
}

#[test]
fn zero_total_budget_stops_before_any_child_solve() {
    let request = request();
    let text = execute(&request.model, options(), Arc::new(Fake(|model: &LinearTriadModel| terminal(model, TerminationReason::Completed))),
        &SolveOptions { cancellation_handle: Some(&SolveHandle::new()), time_limit: Some(std::time::Duration::ZERO), ..Default::default() }).unwrap();
    let report = decode_bpp3d_execution_report(&text, &request.model).unwrap();
    assert!(!report.summary.completed && report.summary.stage_count == 1);
    assert_eq!(report.stages[0].termination_reason.as_deref(), Some("TIME_LIMIT"));
    assert!(report.packing.is_none());
}

